// ---- projected PF from two teams
{
  const good = JSON.stringify({ as_of: "2026-10-18", teams: {
    BOS: { last10: 19.5, season: 20.1, games_this_season: 12 },
    DET: { last10: 22.0, season: 21.4, games_this_season: 12 },
    NYK: { last10: 20.0, season: null, games_this_season: 0 },
    SAN: { last10: 18.0, season: 19.0, games_this_season: 3 },
  } });
  const p = E.parseTeamFouls(good);
  check("team data: parses", p.errors.length === 0 && Object.keys(p.data.teams).length === 4, JSON.stringify(p.errors));
  const r = E.projectedPf("BOS", "DET", p.data, "2026-10-19");
  check("PF = (A.last10 + B.last10 + A.season + B.season) / 2", Math.abs(r.pf - (19.5 + 22.0 + 20.1 + 21.4) / 2) < 1e-12, String(r.pf));
  check("PF is symmetric in the two teams", Math.abs(E.projectedPf("DET", "BOS", p.data, "2026-10-19").pf - r.pf) < 1e-12);
  check("no notes when the data is fresh and complete", r.notes.length === 0 && r.fallback === false, JSON.stringify(r.notes));
  const f = E.projectedPf("BOS", "NYK", p.data, "2026-10-19");
  check("missing season half falls back to last10 and says so", f.fallback === true && Math.abs(f.pf - (19.5 + 20.0 + 20.1 + 20.0) / 2) < 1e-12 && f.notes.length === 1, JSON.stringify(f));
  const e = E.projectedPf("SAN", "BOS", p.data, "2026-10-19");
  check("few games this season is flagged", e.notes.some((n) => /only 3 games/.test(n)), JSON.stringify(e.notes));
  const old = E.projectedPf("BOS", "DET", p.data, "2026-10-25");
  check("stale data is flagged", old.notes.some((n) => /7 days old/.test(n)), JSON.stringify(old.notes));
  check("same team twice is refused", throwsMatching(() => E.projectedPf("BOS", "BOS", p.data, "2026-10-19"), /different teams/));
  check("team with no data is refused", throwsMatching(() => E.projectedPf("BOS", "LAL", p.data, "2026-10-19"), /No data for LAL/));
  check("bad JSON gets a plain message", /first \{/.test(E.parseTeamFouls("not json").errors[0]));
  check("unknown team code is rejected", E.parseTeamFouls(JSON.stringify({ as_of: "2026-10-18", teams: { XXX: { last10: 19, season: 19 } } })).errors.length >= 1);
  check("absurd average is rejected", E.parseTeamFouls(JSON.stringify({ as_of: "2026-10-18", teams: { BOS: { last10: 190, season: 19 } } })).data === null);
  check("bad date is rejected", E.parseTeamFouls(JSON.stringify({ as_of: "yesterday", teams: { BOS: { last10: 19, season: 19 } } })).data === null);
  check("30 team names, all codes upper-case", Object.keys(E.TEAM_NAMES).length === 30 && Object.keys(E.TEAM_NAMES).every((k) => k === k.toUpperCase() && k.length === 3));
  check("lower-case team codes are accepted", E.parseTeamFouls(JSON.stringify({ as_of: "2026-10-18", teams: { bos: { last10: 19, season: 19 } } })).data !== null);
}

